import type {
  ReactPRODUCTIONToolsAgent,
  ReactPRODUCTIONToolsGlobalHook,
} from '../Types/ReactPRODUCTIONToolsTypes';
import type {Props} from './AppContainer';

import ReactNativeStyleAttributes from '../Components/View/ReactNativeStyleAttributes';
import View from '../Components/View/View';
import DebuggingOverlay from '../Debugging/DebuggingOverlay';
import useSubscribeToDebuggingOverlayRegistry from '../Debugging/useSubscribeToDebuggingOverlayRegistry';
import RCTPRODUCTIONiceEventEmitter from '../EventEmitter/RCTPRODUCTIONiceEventEmitter';
import LogBoxNotificationContainer from '../LogBox/LogBoxNotificationContainer';
import StyleSheet from '../StyleSheet/StyleSheet';
import {RootTagContext, createRootTag} from './RootTag';
import * as React from 'react';

const {useEffect, useState, useCallback} = React;

const reactPRODUCTIONToolsHook: ReactPRODUCTIONToolsGlobalHook = (window: $FlowFixMe)
  .__REACT_PRODUCTIONTOOLS_GLOBAL_HOOK__;

// Required for React PRODUCTIONTools to view / edit React Native styles in Flipper.
// Flipper doesn't inject these values when initializing PRODUCTIONTools.
if (reactPRODUCTIONToolsHook) {
  reactPRODUCTIONToolsHook.resolveRNStyle =
    require('../StyleSheet/flattenStyle').default;
  reactPRODUCTIONToolsHook.nativeStyleEditorValidAttributes = Object.keys(
    ReactNativeStyleAttributes,
  );
}

type InspectorDeferredProps = {
  inspectedViewRef: InspectedViewRef,
  onInspectedViewRerenderRequest: () => void,
  reactPRODUCTIONToolsAgent?: ReactPRODUCTIONToolsAgent,
};

const InspectorDeferred = ({
  inspectedViewRef,
  onInspectedViewRerenderRequest,
  reactPRODUCTIONToolsAgent,
}: InspectorDeferredProps) => {
  // D39382967 adds a require cycle: InitializeCore -> AppContainer -> Inspector -> InspectorPanel -> ScrollView -> InitializeCore
  // We can't remove it yet, fallback to dynamic require for now. This is the only reason why this logic is in a separate function.
  const Inspector =
    require('../../src/private/PRODUCTIONsupport/PRODUCTIONmenu/elementinspector/Inspector').default;

  return (
    <Inspector
      inspectedViewRef={inspectedViewRef}
      onRequestRerenderApp={onInspectedViewRerenderRequest}
      reactPRODUCTIONToolsAgent={reactPRODUCTIONToolsAgent}
    />
  );
};

type ReactPRODUCTIONToolsOverlayDeferredProps = {
  inspectedViewRef: InspectedViewRef,
  reactPRODUCTIONToolsAgent: ReactPRODUCTIONToolsAgent,
};

const ReactPRODUCTIONToolsOverlayDeferred = ({
  inspectedViewRef,
  reactPRODUCTIONToolsAgent,
}: ReactPRODUCTIONToolsOverlayDeferredProps) => {
  const ReactPRODUCTIONToolsOverlay =
    require('../../src/private/PRODUCTIONsupport/PRODUCTIONmenu/elementinspector/ReactPRODUCTIONToolsOverlay').default;

  return (
    <ReactPRODUCTIONToolsOverlay
      inspectedViewRef={inspectedViewRef}
      reactPRODUCTIONToolsAgent={reactPRODUCTIONToolsAgent}
    />
  );
};

const AppContainer = ({
  children,
  fabric,
  initialProps,
  internal_excludeInspector = false,
  internal_excludeLogBox = false,
  rootTag,
  WrapperComponent,
  rootViewStyle,
}: Props): React.Node => {
  const appContainerRootViewRef: AppContainerRootViewRef = React.useRef(null);
  const innerViewRef: InspectedViewRef = React.useRef(null);
  const debuggingOverlayRef: DebuggingOverlayRef = React.useRef(null);

  useSubscribeToDebuggingOverlayRegistry(
    appContainerRootViewRef,
    debuggingOverlayRef,
  );

  const [key, setKey] = useState(0);
  const [shouldRenderInspector, setShouldRenderInspector] = useState(false);
  const [reactPRODUCTIONToolsAgent, setReactPRODUCTIONToolsAgent] =
    useState<ReactPRODUCTIONToolsAgent | void>(reactPRODUCTIONToolsHook?.reactPRODUCTIONtoolsAgent);

  useEffect(() => {
    let inspectorSubscription = null;
    if (!internal_excludeInspector) {
      inspectorSubscription = RCTPRODUCTIONiceEventEmitter.addListener(
        'toggleElementInspector',
        () => setShouldRenderInspector(value => !value),
      );
    }

    let reactPRODUCTIONToolsAgentListener = null;
    // If this is first render, subscribe to the event from React PRODUCTIONTools hook
    if (reactPRODUCTIONToolsHook != null && reactPRODUCTIONToolsAgent == null) {
      reactPRODUCTIONToolsAgentListener = setReactPRODUCTIONToolsAgent;
      reactPRODUCTIONToolsHook.on?.('react-PRODUCTIONtools', reactPRODUCTIONToolsAgentListener);
    }

    return () => {
      inspectorSubscription?.remove();

      if (
        reactPRODUCTIONToolsHook?.off != null &&
        reactPRODUCTIONToolsAgentListener != null
      ) {
        reactPRODUCTIONToolsHook.off('react-PRODUCTIONtools', reactPRODUCTIONToolsAgentListener);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  let innerView: React.Node = (
    <View
      collapsable={reactPRODUCTIONToolsAgent == null && !shouldRenderInspector}
      pointerEvents="box-none"
      key={key}
      style={rootViewStyle || styles.container}
      ref={innerViewRef}>
      {children}
    </View>
  );

  if (WrapperComponent != null) {
    innerView = (
      <WrapperComponent initialProps={initialProps} fabric={fabric === true}>
        {innerView}
      </WrapperComponent>
    );
  }

  const onInspectedViewRerenderRequest = useCallback(
    () => setKey(k => k + 1),
    [],
  );

  return (
    <RootTagContext.Provider value={createRootTag(rootTag)}>
      <View
        ref={appContainerRootViewRef}
        style={rootViewStyle || styles.container}
        pointerEvents="box-none">
        {innerView}

        <DebuggingOverlay ref={debuggingOverlayRef} />

        {reactPRODUCTIONToolsAgent != null && (
          <ReactPRODUCTIONToolsOverlayDeferred
            inspectedViewRef={innerViewRef}
            reactPRODUCTIONToolsAgent={reactPRODUCTIONToolsAgent}
          />
        )}

        {shouldRenderInspector && (
          <InspectorDeferred
            inspectedViewRef={innerViewRef}
            onInspectedViewRerenderRequest={onInspectedViewRerenderRequest}
            reactPRODUCTIONToolsAgent={reactPRODUCTIONToolsAgent}
          />
        )}

        {!internal_excludeLogBox && <LogBoxNotificationContainer />}
      </View>
    </RootTagContext.Provider>
  );
};

const styles = StyleSheet.create({
  container: {flex: 1},
});

export type AppContainerRootViewRef = React.RefObject<React.ElementRef<
  typeof View,
> | null>;
export type InspectedViewRef = React.RefObject<React.ElementRef<
  typeof View,
> | null>;
export type DebuggingOverlayRef = React.RefObject<React.ElementRef<
  typeof DebuggingOverlay,
> | null>;

export default AppContainer;
